import{_ as t,o as a,c as d,a2 as o}from"./chunks/framework.BvnCBqQl.js";const u=JSON.parse('{"title":"Lab 5：mini-dify v0.5 —— 知识库 RAG","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/lab-5-rag.md","filePath":"chapters/lab-5-rag.md","lastUpdated":1791442702000}'),s={name:"chapters/lab-5-rag.md"};function i(c,e,n,l,r,p){return a(),d("div",null,[...e[0]||(e[0]=[o(`<h1 id="lab-5-mini-dify-v0-5-——-知识库-rag" tabindex="-1">Lab 5：mini-dify v0.5 —— 知识库 RAG <a class="header-anchor" href="#lab-5-mini-dify-v0-5-——-知识库-rag" aria-label="Permalink to &quot;Lab 5：mini-dify v0.5 —— 知识库 RAG&quot;">​</a></h1><blockquote><p>目标：创建知识库，上传文档（txt / md / pdf / html，或直接粘贴文本），在后台完成提取、清洗、分段、向量化、存储；支持向量、BM25、混合三种检索和父子分段；在工作流中用知识检索节点 + LLM 上下文实现 RAG。 起点 <code>v0.4</code>，终点 <code>v0.5</code>。</p></blockquote><h2 id="依赖" tabindex="-1">依赖 <a class="header-anchor" href="#依赖" aria-label="Permalink to &quot;依赖&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;pypdf&gt;=4&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;python-multipart&gt;=0.0.9&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;numpy&gt;=1.26&quot;</span></span></code></pre></div><p><code>python-multipart</code> 是 FastAPI 处理文件上传（<code>UploadFile</code>、<code>Form</code>）所必需的。</p><h2 id="构建顺序" tabindex="-1">构建顺序 <a class="header-anchor" href="#构建顺序" aria-label="Permalink to &quot;构建顺序&quot;">​</a></h2><table tabindex="0"><thead><tr><th>步骤</th><th>文件</th><th>章节</th></tr></thead><tbody><tr><td>1</td><td><code>app/rag/processing.py</code>：<code>extract_text</code>、<code>clean_text</code>、<code>recursive_split</code>、<code>_merge</code>、<code>split_document</code></td><td>22</td></tr><tr><td>2</td><td><code>app/models.py</code>：<code>Dataset</code>、<code>Document</code>（<code>raw_content</code>、<code>status</code>）、<code>Segment</code>（<code>vector</code>、<code>parent_content</code>）、<code>EmbeddingCache</code></td><td>22</td></tr><tr><td>3</td><td><code>app/rag/index.py</code>：<code>embed_texts</code>（带缓存）、<code>tokenize</code>、<code>bm25_scores</code>、<code>retrieve</code>、<code>format_context</code></td><td>22、23</td></tr><tr><td>4</td><td><code>app/rag/indexing.py</code>：<code>index_document</code>（状态流转）、<code>index_in_background</code></td><td>22</td></tr><tr><td>5</td><td><code>app/api/datasets.py</code>：知识库、文档上传（multipart）、分段查看、召回测试</td><td>23</td></tr><tr><td>6</td><td><code>app/workflow/nodes/knowledge.py</code>；LLM 节点增加 <code>context</code> 配置</td><td>23</td></tr><tr><td>7</td><td>前端：<code>pages/DatasetsPage.tsx</code>（列表 / 创建 / 详情 / 召回测试，索引期间轮询状态）、知识检索节点面板、LLM 面板的“上下文”字段</td><td>23</td></tr></tbody></table><h2 id="演示" tabindex="-1">演示 <a class="header-anchor" href="#演示" aria-label="Permalink to &quot;演示&quot;">​</a></h2><ol><li>知识库 → 创建“产品手册”（通用分段，分段最大长度 120）；</li><li>粘贴下面这段文本：</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第一章 安装。后端使用 FastAPI，运行 uv sync 安装依赖，然后用 uvicorn 启动服务。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第二章 工作流。工作流由节点和边组成，引擎按照拓扑顺序执行节点，支持条件分支与并行。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第三章 退款政策。购买后七天内可以无理由退款，超过七天需要提供质量问题证明。</span></span></code></pre></div><ol start="3"><li>状态变为“可用”后，点击文档名，能看到 3 个分段；</li><li>召回测试：问“怎么退款”，选择混合检索，第一条结果是第三章；</li><li>再创建一个“父子分段”知识库，用同样的文本，问“超过七天需要什么”，返回的是第三章的完整段落；</li><li>新建 Chatflow，按第 23 章 23.4 节的步骤搭建 RAG 流程，然后提问。</li></ol><h2 id="验收清单" tabindex="-1">验收清单 <a class="header-anchor" href="#验收清单" aria-label="Permalink to &quot;验收清单&quot;">​</a></h2><ul><li>[ ] <code>uv run pytest -q</code>：34 个测试通过（v0.5 的数量）</li><li>[ ] 上传 PDF 能提取出文字（扫描版 PDF 没有文字层，提取不到，这是预期的）</li><li>[ ] 索引状态能在前端实时更新；出错的文档显示“出错”，鼠标悬停可以看到原因</li><li>[ ] 三种检索方法都能命中；混合检索的分数由两部分组成</li><li>[ ] RAG 工作流中，LLM 的 prompts 里包含检索到的内容</li></ul><h2 id="写作时踩到的坑-真实记录" tabindex="-1">写作时踩到的坑（真实记录） <a class="header-anchor" href="#写作时踩到的坑-真实记录" aria-label="Permalink to &quot;写作时踩到的坑（真实记录）&quot;">​</a></h2><ol><li><strong>CRLF</strong>：浏览器提交表单时会把换行转换成 <code>\\r\\n</code>，导致 <code>\\n\\n</code> 分隔符失效（第 22 章 22.4 节）。</li></ol><p>另有两个<strong>设计时就规避掉的坑</strong>（不是实际踩到的）：</p><ul><li><strong>BM25 分数的量纲</strong>：BM25 的分数可能是 3.7，余弦相似度却在 0 到 1 之间，直接加权相加的话，关键词分数会完全压倒向量分数。所以先除以最大值归一化。</li><li><strong><code>hash()</code> 的随机盐</strong>：mock embedding 没有使用 Python 内置的 <code>hash()</code>。<code>hash()</code> 对字符串加了每个进程不同的随机盐，单进程测试能过，但 v1.0 里 API 和 Celery Worker 是两个进程，算出的向量会不一样，检索就会悄悄失效。所以从一开始就用了稳定的 FNV-1a。</li></ul>`,17)])])}const g=t(s,[["render",i]]);export{u as __pageData,g as default};
